function settleSetupHash(){if(!window.location.hash)return;let t=window.location.hash.slice(1);try{t=decodeURIComponent(t)}catch{return}const e=document.getElementById(t);e&&e.classList.contains("setup-guide")&&window.setTimeout(()=>{const t=e.getBoundingClientRect().top+window.scrollY-96;window.scrollTo({top:t,behavior:"instant"})},120)}window.addEventListener("pageshow",settleSetupHash),document.fonts?.ready.then(settleSetupHash);